from functools import lru_cache
S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# pieces square and all 4 L orientations. Find exact covers, requiring one square+4 L or 4 squares
placements=[]
for r in range(4):
 for c in range(6):
  cells={(r+i,c+j) for i in range(2) for j in range(2)}
  if cells<=S: placements.append(('square',cells))
  for missing in [(0,0),(0,1),(1,0),(1,1)]:
   cells={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+missing[0],c+missing[1])}
   if cells<=S: placements.append((f'L miss{missing}',cells))
@lru_cache(None)
def rec(remaining, sqneed, lneed):
 rem=set(remaining)
 if not rem: return [] if sqneed==0 and lneed==0 else None
 p=min(rem)
 for typ,cells in placements:
  if p in cells and cells<=rem:
   ns=sqneed-(typ=='square'); nl=lneed-(typ!='square')
   if ns<0 or nl<0:continue
   ans=rec(tuple(sorted(rem-cells)),ns,nl)
   if ans is not None:return [(typ,sorted(cells))]+ans
 return None
for sq,l in [(1,4),(4,0)]:
 ans=rec(tuple(sorted(S)),sq,l)
 print(sq,l,ans)
