from functools import lru_cache
S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
placements=[]
for r in range(4):
 for c in range(6):
  sq={(r+i,c+j) for i in range(2) for j in range(2)}
  if sq<=S: placements.append(('sq',sq))
  for m in [(0,0),(0,1),(1,0),(1,1)]:
   cells={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+m[0],c+m[1])}
   if cells<=S: placements.append((str(m),cells))
sol=[]
def rec(rem,chosen,sq,l):
 if not rem:
  if sq==0 and l==0: sol.append(chosen.copy())
  return
 p=min(rem)
 for typ,cells in placements:
  if p in cells and cells<=rem:
   if typ=='sq' and sq or typ!='sq' and l:
    rec(rem-cells,chosen+[(typ,cells)],sq-(typ=='sq'),l-(typ!='sq'))
rec(set(S),[],1,4)
print('solutions',len(sol))
# Map orientation missing top-left=2 top-right=4 bottom-left=3 bottom-right=1; square=1
for i,ss in enumerate(sol[:6]):
 out=[[0]*7 for _ in range(7)]
 for typ,cells in ss:
  if typ=='sq': col=1
  else:
   m=eval(typ)
   col={(0,0):2,(0,1):4,(1,0):3,(1,1):1}[m]
  for r,c in cells:out[r][c]=col
 print(i, [''.join(map(str,row)) for row in out[:4]])
